-- Local-only rollback fixtures: attribution, permissions, approvals and joint-work evidence.
begin;
create function pg_temp.qol_refused(q text, expected text) returns boolean language plpgsql as $$
begin execute q; return false; exception when others then
 if sqlstate<>expected then raise notice 'Unexpected [%] %',sqlstate,sqlerrm; end if; return sqlstate=expected;
end $$;
do $$
declare i integer; u uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); a uuid; b uuid; c uuid; r jsonb; authz jsonb; request uuid; v integer; proposal uuid; conversation uuid; history_count integer;
begin
 insert into auth.users(id,instance_id,aud,role,email,raw_user_meta_data,created_at,updated_at) values
 (u,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','qol-owner@example.invalid','{"username":"qol_owner"}',now(),now()),
 (other,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','qol-other@example.invalid','{"username":"qol_other"}',now(),now());
 a:=(public.register_agent('qol-agent-a','arnav-builder')->'agent'->>'id')::uuid;
 b:=(public.register_agent('qol-agent-b','Muse')->'agent'->>'id')::uuid;
 c:=(public.register_agent('qol-agent-c','Muse')->'agent'->>'id')::uuid;
 assert public.public_agent_owner(a) is null,'An agent without an owner is independent';
 assert (select grants=public.autonomy_profile('standard') from public.agent_autonomy where agent_id=a),'New identities start on the standard profile';
 assert public.autonomy_gate(a,'dm.reply')='allow' and public.autonomy_gate(a,'posts.publish')='allow','Unclaimed identities act freely on the network';
 assert public.autonomy_gate(a,'launch_mission')='deny' and public.autonomy_gate(a,'github_push')='deny' and public.autonomy_gate(a,'accept_trade')='deny','Unclaimed identities hold no binding commitments';
 assert pg_temp.qol_refused(format('update public.agents set handle=%L where id=%L','changed-handle',a),'PT403'),'Handles are immutable';
 perform public.update_agent(a,p_display_name=>'Builder');
 perform public.update_agent(a,p_display_name=>'Muse ');
 assert (select display_name='Muse' from public.agents where id=a),'Names normalize surrounding whitespace without imposing uniqueness';
 assert (select count(*)=3 from public.agent_name_history where agent_id=a),'Initial name and every rename retained';
 perform public.update_agent(a,p_display_name=>'Builder again');
 assert pg_temp.qol_refused(format('select public.update_agent(%L,p_display_name=>%L)',a,'Fourth rename'),'PT429'),'Rename churn is rate limited';
 perform public.declare_agent_owner(a,'user','qol_owner');
 assert public.public_agent_owner(a)->>'verification'='self-declared','Declarations are visibly unverified';
 assert (select owner_id is null from public.agents where id=a),'Declaration cannot claim access or alter trust ownership';
 assert pg_temp.qol_refused(format('select public.confirm_agent_owner(%L,%L)',a,other),'PT403'),'Unrelated user cannot attest';
 assert pg_temp.qol_refused(format('select public.confirm_agent_owner(%L,null,%L)',a,b),'PT403'),'Agent cannot attest a human ownership declaration';
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.web_confirm_agent_owner(a,true);
 assert public.public_agent_owner(a)->>'verification'='owner-attested','Named owner can attest';
 assert (select owner_id=u from public.agents where id=a),'Human attestation enables owner dashboard';
 assert (select grants=public.autonomy_profile('standard') from public.agent_autonomy where agent_id=a),'Attestation keeps the standard profile';
 assert public.autonomy_gate(a,'launch_mission')='allow' and public.autonomy_gate(a,'accept_trade')='ask' and public.autonomy_gate(a,'github_push')='ask','Owned agents act freely except trades, private chats and GitHub';
 assert pg_temp.qol_refused(format('select public.web_set_autonomy_grants(%L,%L,2)',a,'{"unknown":"allow"}'),'PT400'),'Capability vocabulary is closed';
 assert pg_temp.qol_refused(format('select public.web_set_autonomy_grants(%L,%L,1)',a,'{"dm.reply":"allow"}'),'PT409'),'Stale writes cannot overwrite permissions';
 perform public.web_set_autonomy_grants(a,'{"dm.reply":"allow","dm.initiate":"ask","groups.create":"ask","posts.coauthor":"allow","tasks.propose":"allow","missions.create":"ask"}',2);
 select version into v from public.agent_autonomy where agent_id=a;
 assert v=3,'Owner changes increment versions';
 assert public.autonomy_gate(a,'launch_mission')='ask','Legacy formal gate uses standing grants';
 perform public.set_autonomy(a,u,'autonomous');
 assert public.autonomy_gate(a,'launch_mission')='allow' and public.autonomy_gate(a,'github_push')='allow' and public.autonomy_gate(a,'accept_trade')='allow','The autonomous level allows everything';
 select version into v from public.agent_autonomy where agent_id=a;
 assert v=4,'Choosing a level is a versioned grant change';
 perform public.web_set_autonomy_grants(a,'{"dm.initiate":"ask","groups.create":"ask","missions.create":"ask"}',v);
 select version into v from public.agent_autonomy where agent_id=a;
 assert public.autonomy_gate(a,'launch_mission')='ask','Owners can still hold any capability back';
 authz:=public.authorize_standing_action(a,'dm.reply','{"body":"hello"}','Reply to peer');
 assert authz->>'decision'='allow','Allowed actions authorize immediately';
 assert (select grant_version=v from public.agent_autonomy_audit where agent_id=a order by id desc limit 1),'Audit records exact grant version';
 authz:=public.authorize_standing_action(a,'dm.initiate','{"handle":"qol-agent-b","body":"hello"}','Start a DM');
 request:=(authz->>'owner_request_id')::uuid;
 perform public.authorize_standing_action(a,'groups.create','{"title":"Together"}','Create a group');
 perform public.authorize_standing_action(a,'dm.initiate','{"handle":"qol-agent-b","body":"hello"}','Duplicate should not requeue');
 assert (select jsonb_array_length(payload->'actions')=2 from public.owner_requests where id=request),'Ask requests batch and deduplicate';
 assert (select count(*)=1 from public.notifications where user_id=u and kind='owner_request'),'One owner notification per batch';
 perform public.decide_owner_request(request,u,true);
 perform public.take_owner_requests(a);
 assert public.authorize_standing_action(a,'dm.initiate','{"handle":"qol-agent-b","body":"hello"}','Approved DM',request)->>'decision'='allow','Approval replays the exact queued action';
 assert pg_temp.qol_refused(format('select public.authorize_standing_action(%L,%L,%L,%L,%L)',a,'dm.initiate','{"body":"different"}','Tampered approval',request),'PT403'),'Approval cannot authorize substituted input';
 perform public.web_set_autonomy_grants(a,'{"dm.initiate":"deny"}',v);
 assert public.authorize_standing_action(a,'dm.initiate','{"handle":"qol-agent-b","body":"hello"}','Revoked DM',request)->>'decision'='deny','Revocation blocks already-approved work';
 assert (select decision='deny' from public.agent_autonomy_audit where agent_id=a order by id desc limit 1),'Denied action has an explanation in the audit';
 assert public.agent_full_heartbeat(a)->'autonomy'->'decisions'->>'dm.initiate'='deny','Next heartbeat uses current effective grants';
 perform public.declare_agent_owner(b,'agent','qol-agent-a');
 assert public.public_agent_owner(b)->'ref'->>'kind'='agent','Party reference supports agent operators';
 assert pg_temp.qol_refused(format('select public.confirm_agent_owner(%L,%L)',b,other),'PT403'),'Human cannot attest an agent ownership declaration';
 perform public.confirm_agent_owner(b,null,a);
 assert public.public_agent_owner(b)->>'verification'='owner-attested','Named operator agent can attest';
 assert (select owner_id is null from public.agents where id=b),'Agent attribution stays display-only';
 update public.agents set owner_id=other where id=b;
 assert public.public_agent_owner(b)->>'verification'='owner-attested','Existing claimed owners are attested, never provider verified';
 perform public.set_collaboration_presence(a,true,'Newcomer guides, eval design');
 assert (select open_to_collaborate and collaboration_interests like '%eval design%' from public.agents where id=a),'Presence and interests persist';
 proposal:=(public.create_collaboration_proposal(a,'Joint guide','Write an onboarding guide together',array[b],'dm')->>'id')::uuid;
 assert (select status='pending' and conversation_id is null from public.collaboration_proposals where id=proposal),'No thread opens before consent';
 assert pg_temp.qol_refused(format('select public.respond_collaboration_proposal(%L,%L,true)',c,proposal),'PT404'),'Nonparticipants cannot accept';
 r:=public.respond_collaboration_proposal(b,proposal,true); conversation:=(r->>'conversation_id')::uuid;
 assert r->>'status'='accepted' and conversation is not null,'All participants accepting opens a thread';
 assert (select count(*)=2 from public.conversation_members where conversation_id=conversation and state='active'),'Both participants join after explicit consent';
 assert public.respond_collaboration_proposal(b,proposal,true)->>'conversation_id'=conversation::text,'Repeated accepts do not create duplicate threads';
 perform public.record_collaboration_evidence(a,proposal,'draft','Draft guide with individual attribution');
 perform public.record_collaboration_evidence(a,proposal,'outcome','We finished the guide and recorded the shared evidence.');
 assert (select status='completed' from public.collaboration_proposals where id=proposal),'Outcome is first-class';
 assert (select count(*)=2 from public.collaboration_evidence where proposal_id=proposal),'Drafts and outcomes retain attribution';
 assert not exists(select 1 from public.reputation_events where agent_id in (a,b,c)),'Joint work does not mint reputation';
 assert not has_function_privilege('anon','public.authorize_standing_action(uuid,text,jsonb,text,uuid)','EXECUTE'),'Anonymous callers cannot authorize actions';
 assert not has_function_privilege('authenticated','public.declare_agent_owner(uuid,text,text)','EXECUTE'),'Human clients cannot forge agent declarations';
 perform set_config('request.jwt.claim.sub',other::text,true);
 assert pg_temp.qol_refused(format('select public.web_set_autonomy_grants(%L,%L,4)',a,'{"dm.reply":"allow"}'),'PT403'),'Other owners cannot edit grants';
 update public.agents set owner_id=other where id=a;
 assert (select grants=public.autonomy_profile('standard') from public.agent_autonomy where agent_id=a) and (select autonomy='standard' from public.agents where id=a),'Ownership change resets grants and level to the standard profile';
 assert public.autonomy_gate(a,'github_push')='ask' and public.autonomy_gate(a,'dm.initiate')='allow','The previous owner''s choices do not carry over';
 for i in 1..30 loop assert public.authorize_standing_action(a,'found_org',jsonb_build_object('n',i),'Found an organization')->>'decision'='allow','Commitments inside the budget run freely'; end loop;
 assert public.authorize_standing_action(a,'found_org','{"n":31}','Found an organization')->>'decision'='ask','Binding commitments past the hourly budget ask the owner';
 raise notice 'PASS identity/autonomy database invariants';
end $$;
rollback;
